8 to size-44 range.","tree":{"sha":"eeb5a7fe38301899cbcf2b6b6571096c04688bab","url":"https://api.github.com/repos/stevesioli/portfolio/git/trees/eeb5a7fe38301899cbcf2b6b6571096c04688bab"},"url":"https://api.github.com/repos/stevesioli/portfolio/git/commits/c18495a16c491c07a9c6d400029e4909fbded3fe","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/3331339?v=4","events_url":"https://api.github.com/users/stevesioli/events{/privacy}","followers_url":"https://api.github.com/users/stevesioli/followers","following_url":"https://api.github.com/users/stevesioli/following{/other_user}","gists_url":"https://api.github.com/users/stevesioli/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/stevesioli","id":3331339,"login":"stevesioli","node_id":"MDQ6VXNlcjMzMzEzMzk=","organizations_url":"https://api.github.com/users/stevesioli/orgs","received_events_url":"https://api.github.com/users/stevesioli/received_events","repos_url":"https://api.github.com/users/stevesioli/repos","site_admin":false,"starred_url":"https://api.github.com/users/stevesioli/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/stevesioli/subscriptions","type":"User","url":"https://api.github.com/users/stevesioli","user_view_type":"public"},"html_url":"https://github.com/stevesioli/portfolio/commit/c18495a16c491c07a9c6d400029e4909fbded3fe","node_id":"C_kwDOTQCvC9oAKGMxODQ5NWExNmM0OTFjMDdhOWM2ZDQwMDAyOWU0OTA5ZmJkZWQzZmU","parents":[{"html_url":"https://github.com/stevesioli/portfolio/commit/ad099a28f35f6db203c2b051a89f863ce4135daa","sha":"ad099a28f35f6db203c2b051a89f863ce4135daa","url":"https://api.github.com/repos/stevesioli/portfolio/commits/ad099a28f35f6db203c2b051a89f863ce4135daa"}],"sha":"c18495a16c491c07a9c6d400029e4909fbded3fe","url":"https://api.github.com/repos/stevesioli/portfolio/commits/c18495a16c491c07a9c6d400029e4909fbded3fe"},{"author":{"avat